/**
 * @name base
 * @selector .slds-progress
 * @restrict div
 * @support dev-ready
 * @variant
 */
.slds-progress {
  position: relative;
  max-width: 70%;
  width: 100%;
  flex: 1 1 auto;
  margin: auto;

  .slds-progress-bar {
    position: absolute;
    top: 50%;
    margin-top: (($progress-bar-height * 0.5) * -1);
    background: var(--slds-g-color-neutral-base-50, #{$progress-bar-color-background});
  }
}

/**
  * When on a shaded background such as the modal footer
  *
  * @selector .slds-progress_shade
  * @restrict .slds-progress
  * @modifier
*/
.slds-progress_shade,
.slds-progress--shade {

  .slds-progress__item {

    &.slds-is-completed .slds-progress__marker,
    &.slds-is-active .slds-progress__marker {
      background: var(--slds-g-color-neutral-base-95, #{$progress-color-background-shade});
    }

    &.slds-is-completed .slds-progress__marker_icon,
    &.slds-is-completed .slds-progress__marker--icon {
      border-color: var(--slds-g-color-neutral-base-95, #{$progress-color-background-shade});
    }

    &.slds-is-active .slds-progress__marker {
      box-shadow: var(--slds-g-color-neutral-base-95, #{$progress-color-background-shade}) 0 0 0 4px; // Adds whitespace around indicator

      &:focus {
        box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
        outline: 0;
      }
    }

    &.slds-has-error .slds-progress__marker {

      &,
      &:hover,
      &:focus {
        background: var(--slds-g-color-neutral-base-95, #{$progress-color-background-shade});
      }
    }

    .slds-progress__marker {
      border-color: var(--slds-g-color-neutral-base-95, #{$progress-color-border-shade});
    }
  }
}

/**
 * An ordered list containing steps of a process
 *
 * @selector .slds-progress__list
 * @restrict .slds-progress ol
 * @required
 */
.slds-progress__list {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 100%;
  margin: auto;
  position: relative;
  z-index: $z-index-default;
}

/**
 * A list item for each step of the process
 *
 * @selector .slds-progress__item
 * @restrict .slds-progress ol li
 * @required
 */
.slds-progress__item {
  display: inline-flex;
  align-self: center;

  &.slds-is-completed .slds-progress__marker,
  &.slds-is-active .slds-progress__marker {
    background: var(--slds-g-color-neutral-base-100, #{$progress-color-background});
    border-color: var(--slds-g-color-brand-base-50, #{$progress-color-border-active});
  }

  /**
   * Stateful class for a completed step, `.slds-progress__item` should receive a success icon at this point
   *
   * @selector .slds-is-completed
   * @restrict .slds-progress__item
   * @notes Class should be applied thought JavaScript
   * @required
   * @modifier
   * @group state
   */
  &.slds-is-completed .slds-progress__marker_icon,
  &.slds-is-completed .slds-progress__marker--icon {
    border-color: var(--slds-g-color-neutral-base-100, #{$progress-color-background});
    color: var(--slds-g-color-brand-base-50, #{$progress-bar-color-background-fill});
  }

  /**
   * Stateful class for the active step
   *
   * @selector .slds-is-active
   * @restrict .slds-progress__item
   * @notes Class should be applied thought JavaScript
   * @required
   * @modifier
   * @group state
   */
  &.slds-is-active .slds-progress__marker {
    box-shadow: var(--slds-g-color-neutral-base-100, #{$progress-color-background}) 0 0 0 4px; // Adds whitespace around indicator

    &:hover,
    &:focus {
      border-color: var(--slds-g-color-brand-base-50, #{$progress-color-border-hover});
    }

    &:focus {
      box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
      outline: 0;
    }
  }

  /**
   * Indicates error state for a step in the progress
   *
   * @selector .slds-has-error
   * @restrict .slds-progress__item
   * @required
   * @modifier
   */
  &.slds-has-error .slds-progress__marker {

    &,
    &:hover,
    &:focus {
      color: var(--slds-g-color-error-base-40, #{$color-text-error});
      background: var(--slds-g-color-neutral-base-100, #{$progress-color-background});
      border-color: transparent;
      box-shadow: none;
    }

    &:focus {
      box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
      outline: 0;
    }
  }
}

/**
 * Dot indicator for each step
 *
 * @selector .slds-progress__marker
 * @restrict .slds-progress ol li button, .slds-progress ol li div, .slds-progress ol li span
 * @required
 */
.slds-progress__marker {
  @include square($square-icon-utility-small);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border-radius: $border-radius-circle;
  background: var(--slds-g-color-neutral-base-50, #{$progress-bar-color-background});
  border: 4px solid var(--slds-g-color-neutral-base-100, #{$progress-color-border});
  vertical-align: middle;

  &:focus-visible {
    outline: none;
  }

  &:focus {
    box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
  }
}

/**
  * Modifier that notifies the marker indicator that the step has been completed and its getting an icon
  *
  * @selector .slds-progress__marker_icon
  * @restrict .slds-progress__marker
  * @required
  */
.slds-progress__marker_icon,
.slds-progress__marker--icon {
  @include square(auto);

  .slds-icon {
    fill: currentColor;
  }
}

// Lightning Design System 2.264.1
.slds-progress__item {
  position: relative; // Position context for invisible tap target
  align-items: center;
  min-height: $height-tappable;

  .slds-progress__marker {

    &:before { // Create invisible tap target area
      position: absolute;
      width: calc(100% + 8px); // 8px accounts for border width of container
      height: $height-tappable;
      content: '';
    }
  }
}

.slds-progress__marker {
  @include square($square-tappable-xx-small);
  line-height: 1;
}

.slds-progress__marker_icon {
  @include square($square-tappable-small);

  .slds-icon {
    @include square($square-tappable-xx-small);
  }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @name vertical
 * @selector .slds-progress_vertical
 * @restrict .slds-progress
 * @support dev-ready
 * @variant
 */
.slds-progress_vertical {
  max-width: none;

  .slds-progress__list {
    display: block;
  }

  .slds-progress__item {
    position: relative;
    display: flex;
    align-self: left;
    align-items: center;
    padding: 0;

    &:before,
    &:after {
      content: '';
      position: absolute;
      left: calc((#{$square-icon-utility-small} / 2) - 1px); // "-1px" accounts for half of line width to get true center
      width: 2px;
      background-color: var(--slds-g-color-neutral-base-50, #{$progress-bar-color-background});
    }

    &:before {
      top: 0;
      bottom: 50%;
      @include rtl() {
        right: $spacing-large;
      }
    }

    &:after {
      top: 50%;
      bottom: 0;
      @include rtl() {
        right: $spacing-large;
      }
    }

    &:first-child:before,
    &:last-child:after {
      display: none;
    }

    &.slds-is-completed:before,
    &.slds-is-completed:after,
    &.slds-is-active:before,
    &.slds-has-error:before {
      background-color: var(--slds-g-color-brand-base-50, #{$progress-bar-color-background-fill});
    }
  }

  /**
   * @summary Support content in line with progress marker
   *
   * @selector .slds-progress__item_content
   * @restrict .slds-progress__item div
   */
  .slds-progress__item_content {
    flex: 1;
    align-items: center;
    margin-top: $spacing-small;
    padding-bottom: $spacing-small;
  }

  /**
   * @summary Add borders between progress items
   *
   * @selector .slds-progress__list-bordered
   * @restrict .slds-progress__list
   */
  .slds-progress__list-bordered .slds-progress__item:not(:last-child) .slds-progress__item_content {
    border-bottom: 1px var(--slds-g-color-border-base-1, #{$color-border-separator-alt}) solid;
  }

  .slds-progress__marker {
    display: flex;
    justify-content: center;
    margin-right: $spacing-medium;
    min-width: $square-icon-utility-small;
    z-index: 5;
    @include rtl() {
      margin-left: $spacing-medium;
    }
  }

  .slds-progress__marker_icon {
    border-right: 0;
    border-left: 0;
  }

  .slds-progress__item.slds-is-completed .slds-progress__marker_icon {

    svg {
      fill: var(--slds-g-color-brand-base-60, #{$progress-bar-color-background-fill});
    }
  }

  /**
   * Turn completed stage checkmark green
   *
   * @selector .slds-progress__marker_icon-success
   * @restrict .slds-progress__marker_icon
   */
  .slds-progress__item.slds-is-completed .slds-progress__marker_icon-success {

    svg {
      fill: var(--slds-g-color-success-base-50, #{$progress-bar-color-background-fill-success});
    }
  }

  .slds-progress__item.slds-has-error .slds-progress__marker_icon {

    svg {
      fill: var(--slds-g-color-error-base-40, #{$color-text-error});
    }
  }
}

/**
 * @summary Creates a green bar for the vertical variant
 *
 * @selector .slds-progress_success
 * @restrict .slds-progress_vertical
 */
.slds-progress_success {

  .slds-progress__item {

    &.slds-is-completed:before,
    &.slds-is-completed:after,
    &.slds-is-active:before,
    &.slds-has-error:before {
      opacity: 0.3;
      background-color: var(--slds-g-color-success-base-50, #{$progress-bar-color-background-fill-success});
    }
  }
}

// Lightning Design System 2.264.1
.slds-progress_vertical {

  .slds-progress__item {

    &:before,
    &:after {
      left: calc((#{$square-tappable-xx-small} / 2) - 1px); // "-1px" accounts for half of line width to get true center
    }
  }

  .slds-progress__item_content {
    font-size: $font-size-4;
  }

  .slds-progress__marker {
    width: $square-tappable-xx-small;

    .slds-icon {
      @include square($square-tappable-xx-small);
    }
  }
}
